public CompletableFuture<User> fetchUserAsync(String id) {
    return CompletableFuture.supplyAsync(() -> userRepository.findById(id), executorService)
        .thenApply(user -> enrichUser(user))
        .exceptionally(ex -> { 
            log.error("Failed to fetch user", ex);
            return User.empty(); 
        });
}
